from dataclasses import dataclass
from configparser import BasicInterpolation
from fastcore.all import *
from fastcore.xdg import *
from fastllm.types import haik
from typing import get_type_hints

# %% ../nbs/01_config.ipynb #a3f34f9f
_shell_sage_home_dir = 'shell_sage' # sub-directory of xdg base dir
_shell_sage_cfg_name = 'shell_sage.conf'

# %% ../nbs/01_config.ipynb #9c132dc0
def _cfg_path(): return xdg_config_home() / _shell_sage_home_dir / _shell_sage_cfg_name

# %% ../nbs/01_config.ipynb #9a8ce1d2
@dataclass
class ShellSageConfig:
    model: str = f'anthropic/{haik}'
    search: str = ''
    think: str = ''
    trust: str = ''
    mode: str = 'default'
    api_name: str = ''
    base_url: str = ''
    api_key: str = ''
    history_lines: int = -1
    code_theme: str = "monokai"
    code_lexer: str = "python"
    log: bool = False
    safecmd: bool = False
    custom_instructions: str = ''

# %% ../nbs/01_config.ipynb #38e35cce
class EnvInterpolation(BasicInterpolation):
    def before_get(self, parser, section, option, value, defaults):
        return os.path.expandvars(super().before_get(parser, section, option, value, defaults))

def get_cfg():
    path = _cfg_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    _types = get_type_hints(ShellSageConfig)
    cfg = Config(path.parent, path.name, create=asdict(ShellSageConfig()), types=_types,
        inline_comment_prefixes=('#'), interpolation=EnvInterpolation())
    for k in cfg.d:
        if k not in _types: print(f"Warning: unknown config key '{k}' in {path} (ignored)")
    return cfg
